import subprocess, time
for attempt in range(120):
    result = subprocess.run(['python3', 'bench_ci.py', 'status'], capture_output=True, text=True)
    output = result.stdout + result.stderr
    if attempt == 0 or output != previous:
        print(output, end='' if output.endswith('\n') else '\n', flush=True)
    previous = output
    if result.returncode != 0:
        raise SystemExit(result.returncode)
    lowered = output.lower()
    if any(word in lowered for word in ['success', 'completed', 'failed', 'cancelled', 'canceled']):
        break
    time.sleep(min(10 * (2 ** attempt), 40))
else:
    print('Observation limit reached.', flush=True)
